 65	func prepareEnableCheckpointRemoteSelection(ctx context.Context, opts EnableOptions, explicit, canPrompt bool, selectFn func(context.Context, []huh.Option[string]) (string, error)) (*enableCheckpointRemoteChoice, error) {
 66		choice, err := prepareEnableCheckpointRemote(ctx, opts, explicit)
 67		if err != nil || explicit || !canPrompt || opts.Yes || opts.SkipPushSessions || opts.CheckpointRemote != "" {
 68			return choice, err
 69		}
