159	func selectEnableCheckpointRemote(ctx context.Context, options []huh.Option[string], remoteCount int) (string, error) {
160		var selected string
161		keys := huh.NewDefaultKeyMap()
162		keys.Quit.SetKeys("ctrl+c", "esc")
163		form := NewAccessibleForm(huh.NewGroup(huh.NewSelect[string]().
164			Title("Where should checkpoints go?").
165			Description(fmt.Sprintf("Detected %d Git remotes. Choose where this clone uploads checkpoints. Keeping the current destination changes no destination settings.", remoteCount)).
166			Options(options...).Value(&selected))).WithKeyMap(keys)
167		if err := form.RunWithContext(ctx); err != nil {
168			return "", fmt.Errorf("checkpoint destination form: %w", err)
169		}
170		return selected, nil
171	}
