183	func prepareEnableCheckpointRemote(ctx context.Context, opts EnableOptions, explicit bool) (*enableCheckpointRemoteChoice, error) {
184		choice := &enableCheckpointRemoteChoice{dedicatedRequested: opts.CheckpointRemote != ""}
185		if explicit && opts.CheckpointRemote != "" {
186			return nil, fmt.Errorf("--%s and --%s cannot be combined", flagCheckpointPushRemote, flagCheckpointRemote)
187		}
188		if explicit && opts.CheckpointPushRemote == "" {
189			return nil, fmt.Errorf("--%s must not be empty", flagCheckpointPushRemote)
190		}
191		root, err := paths.WorktreeRoot(ctx)
192		if err != nil {
193			if explicit {
194				return nil, fmt.Errorf("--%s requires an existing git repository: %w", flagCheckpointPushRemote, err)
195			}
196			return choice, nil
197		}
198		s, err := settings.Load(ctx)
199		if err != nil {
200			return nil, fmt.Errorf("cannot read checkpoint destination settings: %w", err)
201		}
202		if !explicit {
203			return choice, nil
204		}
205		remotes, err := pushURLsByRemote(ctx, root)
206		if err != nil {
207			return nil, err
208		}
209		if _, ok := remotes[opts.CheckpointPushRemote]; !ok {
210			return nil, fmt.Errorf("--%s must name a configured Git remote", flagCheckpointPushRemote)
211		}
212		if err := validateCheckpointPushRemote(ctx, root, opts.CheckpointPushRemote); err != nil {
213			return nil, fmt.Errorf("--%s must name a configured Git remote: %w", flagCheckpointPushRemote, err)
214		}
215		if reason := s.LocalLayerRejection(); reason != "" {
216			return nil, fmt.Errorf("cannot save checkpoint destination: local settings ignored: %s", reason)
217		}
218		if _, dedicated, err := remote.PushURL(ctx, opts.CheckpointPushRemote); err != nil {
219			return nil, fmt.Errorf("resolve checkpoint destination: %w", err)
220		} else if dedicated {
221			return nil, fmt.Errorf("--%s cannot replace the effective dedicated checkpoint_remote destination", flagCheckpointPushRemote)
222		}
223		choice.name = opts.CheckpointPushRemote
224		return choice, nil
225	}
226	
227	func validateCheckpointPushRemote(ctx context.Context, root, name string) error {
228		if _, err := gitremote.GetRemoteURLInDir(ctx, root, name); err != nil {
229			return fmt.Errorf("read checkpoint remote URL: %w", err)
230		}
231		// Some Git versions return the remote's name successfully when it has
232		// only pushurl entries. Such a remote has no configured fetch destination.
233		url, err := gitRunner(ctx, root, "config", "--get", "remote."+name+".url")
234		if err != nil || strings.TrimSpace(url) == "" {
235			return fmt.Errorf("remote %q has no configured fetch URL", name)
236		}
237		return nil
238	}
