240	func (c *enableCheckpointRemoteChoice) persist(ctx context.Context) error {
241		if c == nil || c.name == "" || c.saved {
242			return nil
243		}
244		changed, err := settings.SetCheckpointPushRemoteLocal(ctx, c.name)
245		c.changed = changed
246		c.saved = changed || err == nil
247		if err != nil {
248			return fmt.Errorf("save checkpoint destination: %w", err)
249		}
250		return nil
251	}
