253	func (c *enableCheckpointRemoteChoice) report(ctx context.Context, w io.Writer, setupErr error) {
254		if setupErr != nil {
255			if c.changed {
256				fmt.Fprintf(w, "Checkpoint destination saved to %s in .entire/settings.local.json; enable did not complete.\n", c.name)
257			}
258			return
259		}
260		if c.changed {
261			fmt.Fprintf(w, "Checkpoint destination set to: %s\n", c.name)
262			fmt.Fprintln(w, "Saved to .entire/settings.local.json for this clone.")
263		}
264		s, err := settings.Load(ctx)
265		if err != nil {
266			fmt.Fprintf(w, "Cannot determine checkpoint destination: %v\n", err)
267			return
268		}
269		if s.IsPushSessionsDisabled() {
270			c.reportUnchangedDestination(w)
271			fmt.Fprintln(w, "Checkpoint pushing remains disabled.")
272			return
273		}
274		resolved, err := strategy.ResolveCheckpointSyncRemote(ctx)
275		if err != nil {
276			dedicated := false
277			for _, d := range inspectRemoteTopology(ctx).destinations {
278				if !d.pinned {
279					continue
280				}
281				url, effective, urlErr := remote.PushURL(ctx, d.name)
282				if urlErr == nil && effective {
283					fmt.Fprintf(w, "Dedicated checkpoint destination for pushes to %s: %s\n", d.name, gitremote.RedactURLOrPath(url))
284					dedicated = true
285				}
286			}
287			if dedicated {
288				fmt.Fprintf(w, "Cannot resolve checkpoint remote selection: %v. Dedicated checkpoint uploads can still proceed.\n", err)
289				c.reportUnchangedDestination(w)
290				return
291			}
292			fmt.Fprintf(w, "Checkpoint sync remains disabled: %v\n", err)
293			c.reportUnchangedDestination(w)
294			fmt.Fprintf(w, "Choose a configured remote with `entire enable --%s <name>`.\n", flagCheckpointPushRemote)
295			return
296		}
297		if resolved.Name == "" {
298			fmt.Fprintln(w, "No Git remotes configured. Checkpoints stay local until a remote is configured.")
299			c.reportUnchangedDestination(w)
300			return
301		}
302		destination := resolved.Name
303		url, dedicated, err := remote.PushURL(ctx, resolved.Name)
304		if err != nil {
305			fmt.Fprintf(w, "Cannot determine checkpoint destination: %v\n", err)
306			return
307		}
308		if dedicated {
309			destination = gitremote.RedactURLOrPath(url)
310		}
311		root, rootErr := paths.WorktreeRoot(ctx)
312		if !dedicated {
313			eligibilityErr := rootErr
314			if eligibilityErr == nil {
315				eligibilityErr = validateCheckpointPushRemote(ctx, root, resolved.Name)
316			}
317			if eligibilityErr != nil {
318				fmt.Fprintf(w, "Cannot confirm checkpoint uploads to %s: %v\n", resolved.Name, eligibilityErr)
