321				return
322			}
323		}
324		if !c.changed && !c.dedicatedRequested {
325			fmt.Fprintf(w, "Keeping checkpoint destination: %s (%s)\n", destination, checkpointRemoteSourceLabel(resolved.Source))
326		}
